import { createHash, createPrivateKey, createPublicKey, generateKeyPairSync } from 'node:crypto';

/**
 * DNSSEC keys for bind9-hosted zones (3.15): ECDSA P-256 (algorithm 13) combined signing keys, generated by the
 * control plane so every bind9 instance signs with the same keys, and written in bind's key-file format.
 */

export const DNSSEC_ALGORITHM = 13;
/** Zone + secure entry point: a combined signing key (CSK). */
export const DNSKEY_FLAGS = 257;
const DNSKEY_PROTOCOL = 3;
/** SHA-256. */
const DS_DIGEST_TYPE = 2;

export interface DnssecKeyMaterial {
  /** DNSKEY public key field: base64 of x || y. */
  publicKey: string;
  /** base64 of the private scalar d. */
  privateKey: string;
}

export function generateDnssecKey(): DnssecKeyMaterial {
  const { privateKey } = generateKeyPairSync('ec', { namedCurve: 'P-256' });
  const jwk = privateKey.export({ format: 'jwk' });
  const raw = (v: string | undefined) => Buffer.from(v ?? '', 'base64url');

  return {
    publicKey: Buffer.concat([raw(jwk.x), raw(jwk.y)]).toString('base64'),
    privateKey: raw(jwk.d).toString('base64'),
  };
}

/** Whether the private key belongs to the public key (checked before an agent writes key files). */
export function dnssecKeyMatches(key: DnssecKeyMaterial): boolean {
  const pub = Buffer.from(key.publicKey, 'base64');
  const d = Buffer.from(key.privateKey, 'base64');

  if (pub.length !== 64 || d.length !== 32) return false;

  try {
    // SEC1 ECPrivateKey on P-256 without the public key: the point is derived from d.
    const der = Buffer.concat([
      Buffer.from('30310201010420', 'hex'),
      d,
      Buffer.from('a00a06082a8648ce3d030107', 'hex'),
    ]);
    const jwk = createPublicKey(createPrivateKey({ key: der, format: 'der', type: 'sec1' })).export({ format: 'jwk' });

    return Buffer.concat([Buffer.from(jwk.x ?? '', 'base64url'), Buffer.from(jwk.y ?? '', 'base64url')]).equals(pub);
  } catch {
    return false;
  }
}

function dnskeyRdata(publicKey: string): Buffer {
  const header = Buffer.alloc(4);

  header.writeUInt16BE(DNSKEY_FLAGS, 0);
  header.writeUInt8(DNSKEY_PROTOCOL, 2);
  header.writeUInt8(DNSSEC_ALGORITHM, 3);

  return Buffer.concat([header, Buffer.from(publicKey, 'base64')]);
}

/** RFC 4034 appendix B. */
export function dnssecKeyTag(publicKey: string): number {
  const rdata = dnskeyRdata(publicKey);
  let acc = 0;

  for (let i = 0; i < rdata.length; i++) acc += i & 1 ? rdata[i] : rdata[i] << 8;

  acc += (acc >> 16) & 0xffff;

  return acc & 0xffff;
}

function wireName(zone: string): Buffer {
  const labels = zone.replace(/\.$/, '').toLowerCase().split('.');

  return Buffer.concat([
    ...labels.map((l) => Buffer.concat([Buffer.from([l.length]), Buffer.from(l, 'ascii')])),
    Buffer.from([0]),
  ]);
}

export interface DsRecord {
  keyTag: number;
  algorithm: number;
  digestType: number;
  /** Upper-case hex, as registrars display it. */
  digest: string;
}

/** The DS record the parent zone publishes for a key (SHA-256). */
export function dnssecDs(zone: string, publicKey: string): DsRecord {
  return {
    keyTag: dnssecKeyTag(publicKey),
    algorithm: DNSSEC_ALGORITHM,
    digestType: DS_DIGEST_TYPE,
    digest: createHash('sha256')
      .update(Buffer.concat([wireName(zone), dnskeyRdata(publicKey)]))
      .digest('hex')
      .toUpperCase(),
  };
}

export function formatDs(zone: string, ds: DsRecord): string {
  return `${zone.replace(/\.$/, '')}. IN DS ${ds.keyTag} ${ds.algorithm} ${ds.digestType} ${ds.digest}`;
}

export interface BindKeyTimes {
  created: Date;
  /** Set once a successor took over. */
  retired?: Date;
}

const pad = (n: number, width = 2) => String(n).padStart(width, '0');
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function stamp(d: Date): string {
  return `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}`;
}

function stampWithDate(d: Date): string {
  const time = `${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`;

  return `${stamp(d)} (${DAYS[d.getUTCDay()]} ${MONTHS[d.getUTCMonth()]} ${pad(d.getUTCDate())} ${time} ${d.getUTCFullYear()})`;
}

/** `K<zone>.+013+<tag>`: bind's file name stem for a key. */
export function bindKeyFileStem(zone: string, publicKey: string): string {
  return `K${zone.replace(/\.$/, '').toLowerCase()}.+${pad(DNSSEC_ALGORITHM, 3)}+${pad(dnssecKeyTag(publicKey), 5)}`;
}

/**
 * The three files bind's `dnssec-policy` reads for a pregenerated CSK: public key, private key and key state. The
 * state marks the key as both KSK and ZSK so a CSK policy adopts it instead of generating its own.
 */
export function renderBindKeyFiles(
  zone: string,
  key: DnssecKeyMaterial,
  times: BindKeyTimes,
): { key: string; private: string; state: string } {
  const name = `${zone.replace(/\.$/, '').toLowerCase()}.`;
  const tag = dnssecKeyTag(key.publicKey);
  const created = times.created;
  const timing = [`Created: ${stamp(created)}`, `Publish: ${stamp(created)}`, `Activate: ${stamp(created)}`];

  return {
    key: [
      `; This is a key-signing key, keyid ${tag}, for ${name}`,
      `; Created: ${stampWithDate(created)}`,
      `; Publish: ${stampWithDate(created)}`,
      `; Activate: ${stampWithDate(created)}`,
      `${name} 3600 IN DNSKEY ${DNSKEY_FLAGS} ${DNSKEY_PROTOCOL} ${DNSSEC_ALGORITHM} ${key.publicKey}`,
      '',
    ].join('\n'),
    private: [
      'Private-key-format: v1.3',
      `Algorithm: ${DNSSEC_ALGORITHM} (ECDSAP256SHA256)`,
      `PrivateKey: ${key.privateKey}`,
      ...timing,
      '',
    ].join('\n'),
    state: [
      `; This is the state of key ${tag}, for ${name}`,
      `Algorithm: ${DNSSEC_ALGORITHM}`,
      'Length: 256',
      'Lifetime: 0',
      'KSK: yes',
      'ZSK: yes',
      `Generated: ${stampWithDate(created)}`,
      `Published: ${stampWithDate(created)}`,
      `Active: ${stampWithDate(created)}`,
      ...(times.retired ? [`Retired: ${stampWithDate(times.retired)}`] : []),
      '',
    ].join('\n'),
  };
}
